-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 notable NPCs are in' AS assertion, count(*) AS got, 3 AS want
  FROM notable_npcs WHERE slug IN ('overlord-shade', 'overlord-dai', 'spike-the-hangdog-daemonix');
SELECT 'and the notables 20' AS assertion, count(*) AS got, 20 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('overlord-shade', 'overlord-dai', 'spike-the-hangdog-daemonix');

